using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "InspiredEffect", menuName = "Data/Battle/Effects/Moonie/Inspired Effect")]
public class InspiredEffect : LoseEffectEndOfTurnEffect
{
	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().DecreaseEffect(effect, effectAmount);
		return 0;
	}
}
